function recordForm(id){if(!can('technical'))return denied();const r=id?find('records',id):{};if(id&&!canReadRecord(r))return denied();const selected=new URLSearchParams(location.hash.split('?')[1]||'').get('person');return head(id?'Atualizar atendimento':'Registrar atendimento','O acesso depende do papel, do programa e do nível de sigilo.')+'<section class="card form-card">'+wrapForm('record-form',field('Pessoa de referência','person','select',r.person||selected||'u1',peopleOptions())+field('Data','date','date',r.date||today)+field('Tipo de atendimento','type','select',r.type||(role==='psych'?'Psicológico':'Social'),role==='psych'?['Psicológico']:['Social'])+field('Modalidade','scope','select',r.scope||'Individual',['Individual','Familiar','Em grupo'])+field('Participantes adicionais / família','participants','text',r.participants||'',null,true,false)+field('Nível de sigilo','privacy','select',r.privacy||(role==='psych'?'Restrito':'Equipe técnica'),role==='psych'?['Restrito']:['Equipe técnica'])+field('Profissional','professional','text',r.professional||user().name)+field('Relato técnico','content','textarea',r.content||'',null,true)+field('Providências / próximos passos','action','textarea',r.action||'',null,true),'/atendimentos',id?'Salvar nova versão':'Revisar e salvar',hidden('id',id||''))+'</section>'}
