function indicatorsPage(){const ps=scope(db.programs),acts=scope(db.activities).filter(a=>a.date.startsWith(periodFilter)),done=acts.filter(a=>a.status==='Concluída'),att=done.flatMap(a=>Object.values(a.attendance));const present=att.filter(x=>x==='Presente').length;return head('Indicadores que orientam','Uma visão do realizado para planejar os próximos passos.',can('report')?link('Gerar relatório','/relatorios','primary'):'')+filters('','<select id="period-filter" class="filter-control" aria-label="Período dos indicadores"><option value="2026-09" '+(periodFilter==='2026-09'?'selected':'')+'>Setembro 2026</option><option value="2026-08" '+(periodFilter==='2026-08'?'selected':'')+'>Agosto 2026</option></select>')+'<div class="stats">'+stat('Encontros concluídos',done.length,'no período selecionado','calendar')+stat('Presenças registradas',present,'participações nos encontros','people')+stat('Frequência',att.length?Math.round(present/att.length*100)+'<em>%</em>':'—','presenças sobre chamadas','chart')+stat('Horas de atividades',done.reduce((s,a)=>s+Number(a.hours),0),'horas registradas','clock')+'</div><div class="grid-main">'+card('Execução física por programa','Atividades concluídas e cadastradas no período','<div class="chart" role="img" aria-label="Comparativo de atividades por programa">'+ps.map(p=>{const total=acts.filter(a=>a.program===p.id).length,real=done.filter(a=>a.program===p.id).length;return '<div class="chart-column"><span title="'+real+' concluídas" style="height:'+real/Math.max(1,acts.length)*100+'%"></span><span class="plan" title="'+total+' cadastradas" style="height:'+total/Math.max(1,acts.length)*100+'%"></span><small>'+esc(p.short)+'</small></div>'}).join('')+'</div><div class="chart-legend"><span>Concluídas</span><span>Cadastradas</span></div>')+card('Leitura dos resultados','',info('Esta visão utiliza dados agregados, sem identificar as pessoas atendidas.')+'<p class="muted" style="font-size:12px">Os filtros de programa e período são aplicados aos cartões, gráfico e tabela. As metas anuais ficam no plano de cada programa.</p>'+link('Consultar planos de ação','/programas','small'))+'</div><section class="card">'+table(['Programa','Cadastradas','Concluídas','Horas realizadas'],ps.map(p=>{const a=acts.filter(a=>a.program===p.id);return row([esc(p.short),a.length,a.filter(x=>x.status==='Concluída').length,a.filter(x=>x.status==='Concluída').reduce((s,x)=>s+Number(x.hours),0)+' h'])}))+'</section>'}
function integratedContent(ps){return info('Consulta autorizada de execução física e valores financeiros de exemplo. O cadastro e o identificador do programa são únicos.')+table(['Programa / identificador','Execução física anual','Orçado','Realizado financeiro','Saldo'],ps.map(p=>row(['<strong>'+esc(p.short)+'</strong><small>MDCA-'+esc(p.id.toUpperCase())+'</small>',p.realized+' / '+p.target,money(p.budget||0),money(p.spent||0),money((p.budget||0)-(p.spent||0))])))}
function integratedPage(){return head('Um programa, duas perspectivas','Resultados e recursos associados ao mesmo Programa/Projeto.')+filters()+'<section class="card"><div class="card-head"><div><h2>Execução física e financeira</h2><small>Somente consulta · valores ilustrativos do protótipo</small></div>'+badge('Acesso autorizado')+'</div><div class="card-body">'+integratedContent(scope(db.programs))+'</div></section>'}
function reportItems(){if(!reportDraft)return [];return db.activities.filter(a=>accessible(a.program)&&(reportDraft.program==='all'||a.program===reportDraft.program)&&a.date>=reportDraft.start&&a.date<=reportDraft.end)}
function reportIssues(){return reportItems().flatMap(a=>{let x=[];if(a.status!=='Concluída')x.push({item:a.name,reason:'Chamada não concluída',url:'/atividades/'+a.id});if(!a.files.length)x.push({item:a.name,reason:'Nenhuma evidência vinculada',url:'/atividades/'+a.id});if(a.external&&(a.imagePeople||[]).some(id=>!validConsent(person(id))))x.push({item:a.name,reason:'Autorização de imagem pendente',url:'/pessoas'});return x})}
function reportPage(step='configurar'){if(!reportDraft)reportDraft={program:programFilter,start:'2026-09-01',end:'2026-09-30',audience:'Circulação externa',sections:['Objetivos e ações','Atividades e frequência','Indicadores','Evidências']};const r=reportDraft;let body='';
 if(step==='configurar')body='<section class="card form-card">'+stepper(['Configurar','Conferir pendências','Pré-visualizar'],1)+'<form id="report-form"><div class="form-body"><div id="form-error" role="alert"></div><div class="form-grid">'+field('Programa','program','select',r.program,[['all','Todos os programas'],...programOptions()],true)+field('Início do período','start','date',r.start)+field('Fim do período','end','date',r.end)+field('Finalidade','audience','select',r.audience,['Circulação externa','Consulta interna'],true)+'</div><h3 style="margin-top:24px">Conteúdo do relatório</h3>'+['Objetivos e ações','Atividades e frequência','Indicadores','Evidências'].map(s=>'<label class="check-row"><input type="checkbox" name="sections" value="'+s+'" '+(r.sections.includes(s)?'checked':'')+'>'+s+'</label>').join('')+info('Os relatórios usam dados agregados e nomes anonimizados. Relatos técnicos sigilosos não são incluídos.')+'</div><div class="form-actions">'+link('Voltar','/inicio')+'<button class="btn primary">Conferir pendências '+icon('arrow')+'</button></div></form></section>';
 if(step==='pendencias'){const issues=reportIssues();body='<section class="card form-card">'+stepper(['Configurar','Conferir pendências','Pré-visualizar'],2)+'<div class="form-body">'+info(issues.length?issues.length+' pendência(s) encontrada(s). Corrija os registros para a versão final ou visualize uma prévia.':'Todos os registros do período estão prontos para emissão.',issues.length?'amber':'')+table(['Atividade','Pendência',''],issues.map(i=>row([esc(i.item),esc(i.reason),link('Corrigir',i.url,'small')])) )+'</div><div class="form-actions">'+link('Voltar','/relatorios')+link(issues.length?'Visualizar rascunho':'Pré-visualizar relatório','/relatorios/previa','primary')+'</div></section>'}
 if(step==='previa')body='<a class="report-back no-print" href="#/relatorios">← Gerar outro relatório</a><div class="actions no-print" style="justify-content:flex-end;margin-bottom:20px">'+btn('Imprimir / salvar PDF','print','','download')+btn('Exportar XLSX','xlsx','primary','download')+'</div><article class="report-preview"><div class="report-brand">mdca <small>Movimento pelos Direitos da Criança e do Adolescente</small></div><div class="eyebrow">'+(reportIssues().length?'Rascunho · pendências em aberto':'Relatório técnico')+'</div><h1>O cuidado em perspectiva</h1><p>'+date(r.start)+' a '+date(r.end)+' · '+(r.program==='all'?'Todos os programas':esc(pname(r.program)))+'</p>'+info('Documento demonstrativo com dados fictícios e informações pessoais anonimizadas.')+(r.sections.includes('Objetivos e ações')?'<h2>Objetivos e ações</h2>'+programs().filter(p=>r.program==='all'||p.id===r.program).map(p=>'<h3>'+esc(p.short)+'</h3><p>'+esc(p.goal)+'. '+esc(p.action)+'.</p>').join(''):'')+(r.sections.includes('Atividades e frequência')?'<h2>Atividades e frequência</h2>'+table(['Atividade','Data','Situação','Presenças'],reportItems().map(a=>row([esc(a.name),date(a.date),esc(a.status),Object.values(a.attendance).filter(x=>x==='Presente').length]))):'')+(r.sections.includes('Indicadores')?'<h2 style="margin-top:25px">Indicadores do período</h2><p>'+reportItems().filter(a=>a.status==='Concluída').length+' atividades concluídas · '+reportItems().filter(a=>a.status==='Concluída').reduce((s,a)=>s+Number(a.hours),0)+' horas realizadas.</p>':'')+(r.sections.includes('Evidências')?'<h2>Evidências selecionadas</h2><p>'+reportItems().reduce((s,a)=>s+(a.files||[]).length,0)+' arquivo(s) vinculados. A prévia apresenta a quantidade de anexos; fotos e documentos originais não são incorporados a esta demonstração.</p>':'')+(reportIssues().length?'<h2>Pendências da versão</h2><p>'+reportIssues().map(i=>esc(i.item)+': '+esc(i.reason)).join('<br>')+'</p>':'')+'<p class="muted" style="margin-top:30px">Gerado para '+esc(r.audience.toLowerCase())+'. Sem relatos de atendimentos ou identificação dos participantes.</p></article>';
 return head('Relatório técnico','Da execução dos programas à prestação de contas técnica.')+body}
function auditPage(){const logs=db.audit.filter(l=>(!l.program||accessible(l.program))&&(role!=='psych'||l.user===user().name));return head('Trilha de auditoria','Consultas e alterações preservadas para acompanhamento.')+info(role==='psych'?'Você está consultando seus próprios eventos de acesso e alteração.':'Os registros são somente leitura. Usuários comuns não podem alterar ou excluir eventos.')+'<div class="toolbar"><label class="search">'+icon('search')+'<input id="list-search" placeholder="Buscar usuário ou item..." aria-label="Buscar usuário ou item"></label><div class="filters"><select id="audit-type" class="filter-control" aria-label="Tipo de evento"><option value="">Todos os eventos</option>'+[...new Set(logs.map(l=>l.action))].map(a=>'<option>'+esc(a)+'</option>').join('')+'</select><input id="audit-date" class="filter-control" type="date" aria-label="Data do evento"></div></div><section class="card searchable">'+table(['Data e horário','Usuário','Operação','Item',''],logs.map(l=>'<tr data-date="'+l.date.slice(0,10)+'">'+[date(l.date)+'<small>'+esc(l.date.slice(11,16))+'</small>',esc(l.user),badge(l.action,'gray'),esc(l.item),btn('Detalhes','log:'+l.id,'small')].map(c=>'<td>'+c+'</td>').join('')+'</tr>'))+'</section><div id="search-empty" hidden>'+empty()+'</div>'}
function importPage(step='arquivo'){let body='';
 if(step==='arquivo')body=card('Trazer os cadastros existentes','Importe uma amostra CSV para conferir o fluxo.',info('Somente dados fictícios. Arquivos CSV com colunas nome, nascimento, responsavel, familia e programa. Cada registro é validado antes da importação.')+btn('Baixar arquivo de exemplo','sample','','download')+'<form id="import-form"><div id="form-error" role="alert"></div><div class="dropzone">'+icon('upload')+'<p>Selecione o arquivo de cadastros</p><input type="file" name="csv" required accept=".csv,text/csv" aria-label="Arquivo CSV para importação"></div><div class="actions" style="margin-top:18px"><button class="btn primary">Validar arquivo '+icon('arrow')+'</button></div></form>');
 if(step==='validacao'&&importDraft){body=card('Conferência da importação',importDraft.name,info(importDraft.rows.length+' linhas lidas. Colunas reconhecidas: '+importDraft.headers.join(', ')+'.')+table(['Linha','Nome','Programa','Resultado'],importDraft.rows.map((p,i)=>row([i+2,esc(p.name||'Não informado'),esc(p.program),badge(p.issue||'Pronto para importar',p.issue?'amber':'green')])) )+'<div class="actions" style="margin-top:20px">'+link('Escolher outro arquivo','/importacao')+btn('Importar registros válidos','import-confirm','primary','check')+'</div>')}
 if(step==='resultado'){const i=db.imports[0];body=card('Resultado da carga','Comparação entre a origem e os cadastros recebidos',i?'<div class="stats" style="grid-template-columns:repeat(3,1fr)">'+stat('Linhas de origem',i.total,'registros lidos','file')+stat('Importados',i.imported,'cadastros criados','check')+stat('Pendências',i.pending,'linhas não importadas','alert')+'</div>'+info('As linhas com erros permanecem registradas no histórico da carga. Corrija a origem e importe novamente.','amber')+link('Consultar pessoas','/pessoas','primary'):empty())}
 if(!body)body=empty('Selecione um arquivo primeiro','',link('Voltar à importação','/importacao'));
 return head('Importação e piloto','Prepare a transição com conferência dos cadastros.')+tabs([['Carga de dados','/importacao','arquivo'],['Histórico de cargas','/importacao/historico','historico'],['Piloto assistido','/importacao/piloto','piloto']],step)+(step==='historico'?card('Cargas realizadas','',table(['Arquivo','Origem','Importados','Pendências'],db.imports.map(i=>row([esc(i.name),i.total,i.imported,i.pending])))):step==='piloto'?card('Validação do piloto','Acompanhamento da introdução da plataforma','<p class="muted">Registre a revisão dos cadastros, o teste dos fluxos e a orientação da equipe antes de encerrar a fase.</p><form id="pilot-form"><div id="form-error" role="alert"></div>'+['Cadastros conferidos por amostragem','Fluxos de atendimento revisados','Equipe orientada sobre o uso'].map((t,i)=>'<label class="check-row"><input type="checkbox" name="check'+i+'" required '+(db.pilot?'checked':'')+'>'+t+'</label>').join('')+field('Plano de contingência','contingency','textarea',db.contingency||'',null,true,true,'Como o atendimento continua caso a plataforma esteja indisponível.')+'<button style="margin-top:18px" class="btn primary">'+(db.pilot?'Atualizar registro do piloto':'Registrar aprovação do piloto')+'</button></form>'):body)}
function syncPage(){return head('Registros no dispositivo','Acompanhe o envio dos encontros registrados sem conexão.',btn(offline?'Ativar conexão':'Sincronizar agora',offline?'offline':'sync','primary','sync'))+info('Simulação de sincronização: os registros são mantidos neste navegador e incorporados aos dados de demonstração quando a conexão é ativada.',offline?'amber':'')+card('Fila local',db.queue.length+' registro(s) aguardando',db.queue.length?table(['Atividade','Data','Situação'],db.queue.map(a=>row([esc(a.name),date(a.date),badge('Aguardando sincronização','amber')]))):empty('Tudo em dia','Nenhum registro aguardando envio.'))}
function guidePage(){const flows=[['Coordenação','Programas → plano e metas → turma → indicadores → relatório.','coord','/programas','US-01, 02, 04, 10, 11 e 12'],['Registro em campo','Abra uma atividade, faça a chamada e adicione evidências. Simule ficar sem conexão.','educator','/atividades','US-05'],['Acompanhamento social','Consulte uma pessoa, registre uma busca ativa e acompanhe o retorno da rede.','social','/alertas','US-03, 06 e 08'],['Cuidado e sigilo','Abra o atendimento psicológico e consulte suas versões e a trilha de acesso.','psych','/atendimentos','US-07 e 13'],['Aprendizagem','Consulte o contrato de um aprendiz e atualize a jornada teórica e prática.','coord','/aprendizagem','US-09'],['Transição e piloto','Importe o CSV de exemplo, confira a carga e registre a aprovação do piloto.','coord','/importacao','US-14']];
 return head('Explore os caminhos','Um protótipo navegável para a E2 do Módulo de Gestão.',btn('Reiniciar dados de exemplo','reset','','sync'))+info('Protótipo local em HTML, CSS e JavaScript. Dados, login, permissões e sincronização são demonstrativos. As alterações persistem neste navegador. Não há API ou conexão com serviços externos.')+'<div class="guide-grid">'+flows.map((f,i)=>'<section class="card guide-card"><div class="number">0'+(i+1)+'</div><h2>'+f[0]+'</h2><p>'+f[1]+'</p><small>'+f[4]+'</small><div style="margin-top:17px">'+btn('Explorar como '+roles[f[2]].name.split(' ')[0],'tour:'+f[2]+':'+f[3],'primary','arrow')+'</div></section>').join('')+'</div><div class="section-heading"><h2>Estados de interface</h2></div><div class="actions">'+btn('Sem conexão','offline','','cloud')+btn('Acesso negado','denied','','lock')+btn('Sessão expirada','expired','','clock')+btn('Estado vazio','empty-state','','search')+btn('Carregamento','loading-state','','sync')+btn('Erro e recuperação','error-state','','alert')+'</div><div class="section-heading"><h2>Todos os destinos</h2></div><div class="route-list">'+navItems.map(([id,label])=>'<a href="#/'+id+'">'+label+'</a>').join('')+'<a href="#/auditoria">Auditoria</a><a href="#/importacao">Importação e piloto</a><a href="#/integracao">Visão integrada</a><a href="#/sincronizacao">Fila local</a><a href="#/login">Login</a></div><p class="muted">As permissões aqui ilustram o fluxo. A matriz definitiva de papéis deve ser validada pela equipe. O painel institucional usa valores de exemplo; os relatórios calculam os registros salvos no protótipo.</p>'}
